// Simuliert einen Lead genau so, wie ihn der Meta-Lead-Ads-Trigger liefert.
// TYP umstellen, um beide Wege zu testen: 'bewerber' oder 'kunde'
const TYP = 'bewerber';

// Testleads haben eine ID mit "TEST-". Ihre SMS gehen an "test_telefon" aus den Einstellungen,
// nie an die Nummer unten.
const jetzt = new Date().toISOString();

const bewerber = {
  id: 'TEST-' + Date.now(),
  data: {
    full_name: 'Max Mustermann',
    phone_number: '+491700000000',
    email: 'max.mustermann@example.com',
    'welchen_beruf_hast_du?': 'Anlagenmechaniker SHK (Geselle)',
    'hast_du_einen_führerschein_klasse_b?': 'Ja',
    deine_postleitzahl: '70565',
    'wann_könntest_du_bei_uns_starten?': 'In 1–3 Monaten',
  },
  form: { id: '1000000000001', name: 'Recruiting – Anlagenmechaniker SHK', locale: 'de_DE', status: 'ACTIVE' },
  ad: { id: '2000000000001', name: 'Video Drehtag – Team stellt sich vor' },
  adset: { id: '3000000000001', name: 'Stuttgart 30 km – Handwerker 20–55' },
  page: { id: '4000000000001', name: 'Mustermann SHK' },
  created_time: jetzt,
};

const kunde = {
  id: 'TEST-' + Date.now(),
  data: {
    full_name: 'Erika Musterfrau',
    phone_number: '+497110000000',
    email: 'erika.musterfrau@example.com',
    'welches_vorhaben_planen_sie?': 'Badsanierung (komplett)',
    postleitzahl: '70569',
    'wann_soll_es_losgehen?': 'In den nächsten 3 Monaten',
    'welches_budget_haben_sie_eingeplant?': '20.000–30.000 €',
  },
  form: { id: '1000000000002', name: 'Anfrage – Badsanierung', locale: 'de_DE', status: 'ACTIVE' },
  ad: { id: '2000000000002', name: 'Vorher/Nachher Bad Stuttgart' },
  adset: { id: '3000000000002', name: 'Stuttgart 25 km – Eigenheim 35–65' },
  page: { id: '4000000000001', name: 'Mustermann SHK' },
  created_time: jetzt,
};

return [{ json: TYP === 'kunde' ? kunde : bewerber }];

// Bringt jeden Meta-Lead in ein einheitliches Format, egal wie die Formularfragen heißen.
const cfg = $('Einstellungen').item.json;
const roh = $json;

// 1) Formularantworten einsammeln (vereinfachte Ausgabe: data{}, Rohausgabe: field_data[])
const antworten = {};
if (roh.data && typeof roh.data === 'object' && !Array.isArray(roh.data)) {
  Object.assign(antworten, roh.data);
} else {
  for (const f of roh.field_data || []) {
    antworten[f.name] = Array.isArray(f.values) ? f.values.join(', ') : f.values;
  }
}

// 2) Formularfragen per Stichwort erkennen. Eigene Fragen hier ergänzen.
//    Exakte Treffer (z. B. "full_name") gehen vor Teiltreffern.
const STICHWORTE = {
  vorname: ['first_name', 'vorname'],
  nachname: ['last_name', 'nachname'],
  name: ['full_name', 'name'],
  telefon: ['phone_number', 'phone', 'telefon', 'handy', 'mobilnummer'],
  email: ['email', 'e-mail', 'mail'],
  plz: ['zip_code', 'post_code', 'zip', 'postleitzahl', 'plz'],
  ort: ['city', 'wohnort', 'stadt', 'ort'],
  beruf: ['beruf', 'qualifikation', 'ausbildung', 'job_title'],
  fuehrerschein: ['fuehrerschein', 'fahrerlaubnis'],
  vorhaben: ['vorhaben', 'projekt', 'leistung', 'interesse'],
  budget: ['budget', 'investition'],
  zeitpunkt: ['starten', 'wechsel', 'eintritt', 'zeitraum', 'zeitpunkt', 'losgehen', 'wann', 'verfuegbar'],
};

const norm = (s) => String(s ?? '').toLowerCase()
  .replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue').replace(/ß/g, 'ss');

const felder = {};
const vergeben = new Set();
for (const [feld, woerter] of Object.entries(STICHWORTE)) {
  const offen = Object.keys(antworten).filter((k) => !vergeben.has(k));
  const key = offen.find((k) => woerter.includes(norm(k)))
    ?? offen.find((k) => woerter.some((w) => norm(k).includes(w)));
  if (key !== undefined) {
    felder[feld] = String(antworten[key] ?? '').trim();
    vergeben.add(key);
  }
}

// 3) Telefonnummer ins internationale Format bringen (+49...)
const telefonNormieren = (t) => {
  let s = String(t ?? '').replace(/[^\d+]/g, '');
  if (!s) return '';
  if (s.startsWith('00')) s = '+' + s.slice(2);
  else if (s.startsWith('0')) s = '+49' + s.slice(1);
  else if (!s.startsWith('+')) s = '+' + s;
  return s;
};

// 4) Bewerber oder Kunde? Erkennung über den Formularnamen oder eine Berufsfrage.
const formular = roh.form?.name || roh.form_name || '';
const typ = /bewerb|recruit|karriere|job|stelle|azubi|ausbildung/i.test(formular) || Boolean(felder.beruf)
  ? 'Bewerber'
  : 'Kunde';

// 5) Eingangszeit in deutscher Zeit
const zone = cfg.zeitzone || 'Europe/Berlin';
let eingang = typeof roh.created_time === 'number'
  ? DateTime.fromSeconds(roh.created_time)
  : DateTime.fromISO(String(roh.created_time || ''));
if (!eingang.isValid) eingang = DateTime.fromJSDate(new Date(roh.created_time));
if (!eingang.isValid) eingang = DateTime.now();
eingang = eingang.setZone(zone);

const name = felder.name || [felder.vorname, felder.nachname].filter(Boolean).join(' ') || 'Unbekannt';
const telefon = telefonNormieren(felder.telefon);
const leadId = String(roh.id || roh.leadgen_id || 'L-' + Date.now());
const istTest = leadId.startsWith('TEST-');

// Alle übrigen Antworten als lesbarer Text fürs CRM und den Kalender
const STANDARD = ['full_name', 'first_name', 'last_name', 'phone_number', 'email'];
const antwortenText = Object.entries(antworten)
  .filter(([k]) => !STANDARD.includes(k))
  .map(([k, v]) => `${k.replace(/_/g, ' ').replace(/\?$/, '')}: ${v}`)
  .join(' | ');

return {
  json: {
    lead_id: leadId,
    ist_test: istTest,
    eingang: eingang.toFormat('yyyy-MM-dd HH:mm'),
    typ,
    name,
    vorname: felder.vorname || name.split(' ')[0],
    telefon,
    // Testleads bekommen ihre SMS an die eigene Testnummer, nie an die Beispielnummer
    sms_an: istTest ? telefonNormieren(cfg.test_telefon) : telefon,
    email: felder.email || '',
    plz: (felder.plz || felder.ort || '').match(/\d{5}/)?.[0] || '',
    ort: felder.ort || '',
    beruf: felder.beruf || '',
    fuehrerschein: felder.fuehrerschein || '',
    vorhaben: felder.vorhaben || '',
    budget: felder.budget || '',
    zeitpunkt: felder.zeitpunkt || '',
    antworten: antwortenText,
    formular,
    anzeige: roh.ad?.name || '',
    anzeigengruppe: roh.adset?.name || '',
    betrieb: cfg.betrieb_kurz,
  },
};

// Punkte nach den Kriterien aus "Einstellungen". Ab mindest_score gilt der Lead als qualifiziert.
// Bewerber: Beruf 40 · Führerschein 20 · Wohnort 20 · Starttermin 20
// Kunde:    Gebiet 40 · Vorhaben 30 · Zeitpunkt 20 · Budget 10 (unter Mindestbudget: -20)
const cfg = $('Einstellungen').item.json;
const l = $json;

const norm = (s) => String(s ?? '').toLowerCase()
  .replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue').replace(/ß/g, 'ss');
const liste = (s) => String(s ?? '').split(',').map((x) => norm(x).trim()).filter(Boolean);
const KURZFRISTIG = /sofort|direkt|asap|so schnell|naechste|in 1|1\s*(-|–|bis)\s*3|diesen monat|innerhalb/;

let score = 0;
let ausschluss = false;
const gruende = [];

// Pflicht: erreichbare Telefonnummer
if (l.telefon.replace(/\D/g, '').length < 9) {
  ausschluss = true;
  gruende.push('keine gültige Telefonnummer');
}

const praefixe = liste(cfg.plz_praefixe);
const imGebiet = !l.plz ? null : (praefixe.length === 0 || praefixe.some((p) => l.plz.startsWith(p)));
const zeit = norm(l.zeitpunkt);

if (l.typ === 'Bewerber') {
  if (liste(cfg.gesuchte_berufe).some((b) => norm(l.beruf).includes(b))) { score += 40; gruende.push('passender Beruf'); }
  else gruende.push(l.beruf ? `Beruf prüfen (${l.beruf})` : 'Beruf fehlt');

  const fs = norm(l.fuehrerschein);
  if (fs.startsWith('ja') || fs.includes('klasse b') || fs === 'b') { score += 20; gruende.push('Führerschein B'); }
  else if (fs) gruende.push('kein Führerschein');
  else { score += 10; gruende.push('Führerschein offen'); }

  if (imGebiet === true) { score += 20; gruende.push('wohnt im Einzugsgebiet'); }
  else if (imGebiet === null) { score += 10; gruende.push('PLZ fehlt'); }
  else gruende.push('wohnt außerhalb');

  if (KURZFRISTIG.test(zeit)) { score += 20; gruende.push('kurzfristig verfügbar'); }
  else if (zeit) { score += 5; gruende.push('eher später verfügbar'); }
  else { score += 10; gruende.push('Starttermin offen'); }
} else {
  if (imGebiet === true) { score += 40; gruende.push('im Einzugsgebiet'); }
  else if (imGebiet === null) { score += 20; gruende.push('PLZ fehlt'); }
  else { ausschluss = true; gruende.push('außerhalb Einzugsgebiet'); }

  if (liste(cfg.auftrags_stichworte).some((w) => norm(l.vorhaben).includes(w))) { score += 30; gruende.push(`lukratives Vorhaben (${l.vorhaben})`); }
  else gruende.push(l.vorhaben ? `Vorhaben prüfen (${l.vorhaben})` : 'Vorhaben fehlt');

  if (KURZFRISTIG.test(zeit)) { score += 20; gruende.push('zeitnah'); }
  else if (zeit) { score += 5; gruende.push('eher später'); }
  else { score += 10; gruende.push('Zeitpunkt offen'); }

  // "20.000–30.000 €" → 20000, "ab 15k" → 15000
  const b = norm(l.budget).replace(/\./g, '').replace(/\s/g, '');
  const m = b.match(/(\d+)(k|tsd|tausend)?/);
  const budget = m ? Number(m[1]) * (m[2] ? 1000 : 1) : 0;
  if (budget >= Number(cfg.mindest_budget)) { score += 10; gruende.push('Budget passt'); }
  else if (budget > 0) { score -= 20; gruende.push('Budget unter Mindestwert'); }
}

const qualifiziert = !ausschluss && score >= Number(cfg.mindest_score);
const grund = gruende.join(', ');
const du = l.typ === 'Bewerber';

// Texte für SMS und Team-Nachrichten (hier anpassen)
const sms_eingang = du
  ? `Hallo ${l.vorname}, danke für deine Bewerbung bei ${cfg.betrieb_kurz}! Wir melden uns in den nächsten Minuten telefonisch bei dir.`
  : `Guten Tag ${l.name}, danke für Ihre Anfrage bei ${cfg.betrieb_kurz}. Wir melden uns in den nächsten Minuten telefonisch bei Ihnen.`;

const team_pruefen = [
  `🟡 Neuer ${l.typ}: bitte prüfen (Score ${score})`,
  `${l.name} · ${l.telefon}`,
  `Grund: ${grund}`,
  `Antworten: ${l.antworten || '–'}`,
  `Quelle: ${l.anzeige || '–'} / ${l.formular || '–'}`,
  '👉 Jetzt anrufen. Danach im CRM kontakt_status auf "erreicht" setzen.',
].join('\n');

const team_eskalation = `⚠️ Noch nicht angerufen: ${l.name} (${l.telefon}), ${l.typ}, eingegangen um ${l.eingang.slice(11)} Uhr. Bitte sofort anrufen!`;

return {
  json: { ...l, score, qualifiziert, grund, sms_eingang, team_pruefen, team_eskalation },
};

// Sucht den nächsten freien Termin im Zeitfenster aus "Einstellungen".
// Belegte Zeiten kommen aus dem Google Kalender (vorheriger Node, Ausgabe "RAW").
const cfg = $('Einstellungen').item.json;
const lead = $('Vorqualifizierung').item.json;
const zone = cfg.zeitzone || 'Europe/Berlin';

const busy = Object.values($json.calendars || {}).flatMap((c) => c.busy || []);
const belegt = busy.map((b) => ({ s: DateTime.fromISO(b.start).toMillis(), e: DateTime.fromISO(b.end).toMillis() }));

const du = lead.typ === 'Bewerber';
const [von, bis] = String(du ? cfg.zeitfenster_bewerbung : cfg.zeitfenster_besichtigung).split('-').map((t) => t.trim());
const [vonH, vonM = 0] = von.split(':').map(Number);
const [bisH, bisM = 0] = bis.split(':').map(Number);
const dauer = Number(du ? cfg.dauer_bewerbung_min : cfg.dauer_besichtigung_min);
const tage = String(cfg.arbeitstage).split(',').map(Number); // 1 = Montag ... 7 = Sonntag
const heute = DateTime.now().setZone(zone).startOf('day');
const frueheste = DateTime.now().setZone(zone).plus({ hours: Number(cfg.vorlauf_stunden) });
const suchTage = Number(cfg.suchzeitraum_tage);

let start = null;
let hinweis = '';
for (let d = 0; d <= suchTage && !start; d++) {
  const tag = heute.plus({ days: d });
  if (!tage.includes(tag.weekday)) continue;
  const ende = tag.set({ hour: bisH, minute: bisM });
  for (let s = tag.set({ hour: vonH, minute: vonM }); s.plus({ minutes: dauer }) <= ende; s = s.plus({ minutes: dauer })) {
    const e = s.plus({ minutes: dauer });
    const frei = !belegt.some((b) => s.toMillis() < b.e && e.toMillis() > b.s);
    if (s >= frueheste && frei) { start = s; break; }
  }
}

// Kein freier Slot im Suchzeitraum: ersten Arbeitstag danach nehmen und markieren
if (!start) {
  hinweis = 'kein freier Slot im Suchzeitraum, bitte prüfen';
  for (let d = suchTage + 1; !start; d++) {
    const tag = heute.plus({ days: d });
    if (tage.includes(tag.weekday)) start = tag.set({ hour: vonH, minute: vonM });
  }
}

const ende = start.plus({ minutes: dauer });
const WOCHENTAG = ['Mo', 'Di', 'Mi', 'Do', 'Fr', 'Sa', 'So'];
const termin_text = `${WOCHENTAG[start.weekday - 1]}, ${start.toFormat('dd.MM.')} um ${start.toFormat('HH:mm')} Uhr`;

const sms_termin = du
  ? `Hallo ${lead.vorname}, danke für deine Bewerbung bei ${cfg.betrieb_kurz}! Wir haben dir ein Kennenlernen reserviert: ${termin_text}, ${cfg.betrieb_adresse}. Wir rufen dich gleich kurz an. Passt es nicht? Hier umbuchen: ${cfg.umbuchungslink}`
  : `Guten Tag ${lead.name}, danke für Ihre Anfrage bei ${cfg.betrieb_kurz}. Wir haben Ihnen einen Vor-Ort-Termin reserviert: ${termin_text}. Wir rufen Sie gleich zur Bestätigung an. Umbuchen: ${cfg.umbuchungslink}`;

const team_termin = [
  `✅ Neuer ${lead.typ}: Termin gebucht (Score ${lead.score})`,
  `${lead.name} · ${lead.telefon}`,
  `Termin: ${termin_text}${hinweis ? ` (${hinweis})` : ''}`,
  `Grund: ${lead.grund}`,
  `Quelle: ${lead.anzeige || '–'} / ${lead.formular || '–'}`,
  '👉 Jetzt anrufen und Termin bestätigen. Danach im CRM kontakt_status auf "erreicht" setzen.',
].join('\n');

return {
  json: {
    termin_start: start.toISO(),
    termin_ende: ende.toISO(),
    termin_text,
    termin_hinweis: hinweis,
    termin_titel: `${du ? 'Bewerbungsgespräch' : 'Vor-Ort-Termin'}: ${lead.name}${hinweis ? ' (prüfen)' : ''}`,
    termin_ort: du ? cfg.betrieb_adresse : [lead.plz, lead.ort].filter(Boolean).join(' '),
    sms_termin,
    team_termin,
  },
};
